type Profile = { name: string };
export const rename = (profile: Profile, name: string): void => {
  profile.name = name;
};

export const append = (list: number[], value: number): void => {
  list.push(value);
};

export const strip = (record: { extra?: string }): void => {
  delete record.extra;
};

